"""Built-in lighting presets and Blender conversions."""

from collections.abc import Mapping
from dataclasses import dataclass
from math import atan
from types import MappingProxyType
from typing import Literal

type RGB = tuple[float, float, float]
type MatrixRow = tuple[float, float, float, float]
type Matrix4x4 = tuple[MatrixRow, MatrixRow, MatrixRow, MatrixRow]
type LightType = Literal["ambient", "distant"]
type RigLightPresetName = Literal[
    "BUILD_FL",
    "BUILD_FR",
    "BUILD_RL",
    "BUILD_RR",
    "MECHANIC_FL",
    "MECHANIC_FR",
    "MECHANIC_RL",
    "MECHANIC_RR",
]
type LightPresetName = Literal["DEFAULT", "NO_LIGHT"] | RigLightPresetName


@dataclass(frozen=True, slots=True)
class LightSpec:
    """Position, size, and intensity of one preset light."""

    name: str
    type: LightType
    matrix: Matrix4x4
    color: RGB
    strength: float
    size: float


def distant_size_to_sun_angle(size: float) -> float:
    """Convert a preset's half-angle size to Blender's full sun angle."""

    return 2.0 * atan(size)


