def _build_lights(primary: str) -> tuple[LightSpec, ...]:
    return tuple(
        LightSpec(name, "distant", matrix, (1.0, 1.0, 1.0), 3.0 if name == primary else 1.0, 1.0)
        for name, matrix in _BUILD_MATRICES.items()
    )


