def _mechanic_lights(preset: RigLightPresetName) -> tuple[LightSpec, ...]:
    return tuple(
        LightSpec(name, "distant", matrix, *_MECHANIC_PROPERTIES[name])
        for name, matrix in _MECHANIC_MATRICES[preset].items()
    )


LIGHT_PRESETS: Mapping[LightPresetName, tuple[LightSpec, ...]] = MappingProxyType(
    {
        "DEFAULT": _DEFAULT_LIGHTS,
        "BUILD_FL": _build_lights("Light_FL"),
        "BUILD_FR": _build_lights("Light_FR"),
        "BUILD_RL": _build_lights("Light_RL"),
        "BUILD_RR": _build_lights("Light_RR"),
        "MECHANIC_FL": _mechanic_lights("MECHANIC_FL"),
        "MECHANIC_FR": _mechanic_lights("MECHANIC_FR"),
        "MECHANIC_RL": _mechanic_lights("MECHANIC_RL"),
        "MECHANIC_RR": _mechanic_lights("MECHANIC_RR"),
        "NO_LIGHT": (),
    }
)

LIGHT_RIG_PRESET_NAMES: tuple[RigLightPresetName, ...] = tuple(
    name for name in LIGHT_PRESETS if name.startswith(("BUILD_", "MECHANIC_"))
)
LIGHT_PRESET_NAMES: tuple[LightPresetName, ...] = tuple(LIGHT_PRESETS)
